import { openDatabase, nowIso } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a process that no longer exists. Requeue it for recovery.
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, retry_at=0, updated_at=? WHERE status='running'").run(nowIso());
const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat(id,at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET at=excluded.at`).run(Date.now());
interface Claimed { id:string; input:string; steps:number; fail_attempts:number; attempts:number; }
function claim(): Claimed | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT id,input,steps,fail_attempts,attempts FROM jobs WHERE status='queued' AND retry_at<=? ORDER BY created_at ASC,rowid ASC LIMIT 1").get(Date.now()) as Claimed | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const attempt = Math.min(3, Number(row.attempts) + 1);
    db.prepare("UPDATE jobs SET status='running', attempts=?, progress_completed=0, result_output=NULL, error=NULL, updated_at=? WHERE id=? AND status='queued'").run(attempt, nowIso(), row.id);
    db.exec('COMMIT');
    return { ...row, attempts: attempt };
  } catch (err) { db.exec('ROLLBACK'); throw err; }
}
async function processJob(job: Claimed): Promise<void> {
  const fail = job.attempts <= Number(job.fail_attempts);
  if (fail) {
    await sleep(100);
    const stamp = nowIso();
    if (job.attempts >= 3) {
      db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, progress_completed=0, updated_at=? WHERE id=? AND status='running'").run(stamp, job.id);
    } else {
      db.prepare("UPDATE jobs SET status='queued', error=NULL, progress_completed=0, retry_at=?, updated_at=? WHERE id=? AND status='running'").run(Date.now() + 500, stamp, job.id);
