  }
  for (let step = 1; step <= Number(job.steps) && !stopping; step++) {
    await sleep(100);
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(step, nowIso(), job.id);
  }
  if (stopping) return;
  db.prepare("UPDATE jobs SET status='completed', result_output=?, error=NULL, progress_completed=steps, updated_at=? WHERE id=? AND status='running'")
    .run(String(job.input).toUpperCase(), nowIso(), job.id);
}

console.log('worker started');
while (!stopping) {
  heartbeat();
  try {
    const job = claim();
    if (job) await processJob(job); else await sleep(100);
  } catch (err) {
    console.error('worker loop error', err);
    await sleep(200);
  }
