    const form = document.querySelector('[data-testid="job-form"]');
    const alertBox = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    const input = document.querySelector('[data-testid="job-input"]');
    const steps = document.querySelector('[data-testid="job-steps"]');
    const failAttempts = document.querySelector('[data-testid="job-fail-attempts"]');
    function render(jobs) {
      list.replaceChildren(...jobs.map(job => {
        const item = document.createElement('li'); item.dataset-testid = 'job-item'; item.dataset.jobId = job.id;
        const heading = document.createElement('strong'); heading.textContent = job.input;
        const status = document.createElement('span'); status.dataset-testid = 'job-status'; status.textContent = job.status;
        const progress = document.createElement('span'); progress.dataset-testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
        const result = document.createElement('div'); result.dataset-testid = 'job-result'; result.textContent = job.result ? job.result.output : (job.error || '');
        const meta = document.createElement('div'); meta.className = 'meta'; meta.append('Status: ', status, ' · Progress: ', progress);
        item.append(heading, meta, result); return item;
      }));
    }
    async function refresh() {
      try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); } catch (_) {}
    }
    form.addEventListener('submit', async event => {
      event.preventDefault(); alertBox.textContent = '';
      const payload = { input: input.value, steps: Number(steps.value), failAttempts: Number(failAttempts.value) };
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
        const data = await response.json();
        if (!response.ok) {
          const fields = data.error && data.error.fields || [];
          alertBox.textContent = fields.length ? fields.map(field => `${field.field}: ${field.message}`).join(' ') : data.error.message;
        } else { input.value = ''; await refresh(); }
      } catch (_) { alertBox.textContent = 'Unable to submit the job. Please try again.'; }
    });
    refresh(); setInterval(refresh, 500);
  </script>
